 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # First handle a set of uniform horizontal bands with one missing band.
    row_colors = []
    uniform_rows = True
    for row in grid:
        vals = {v for v in row if v != 0}
        if len(vals) > 1:
            uniform_rows = False
            break
        row_colors.append(next(iter(vals)) if vals else None)
    if uniform_rows and any(v is None for v in row_colors):
        known = [v for v in row_colors if v is not None]
        fill = known[-1]
        return [[fill if v is None else v for v in (row_colors[r],)] * w
                for r in range(h)]

    # Otherwise the colored diagonals (constant column-row) encode one period
    # of a diagonal repeating pattern. Infer the shortest period that assigns
    # every residue class exactly one observed color.
    bands = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color:
                d = c - r
                if d in bands and bands[d] != color:
                    return [row[:] for row in grid]
                bands[d] = color

    if not bands:
        return [row[:] for row in grid]

    for period in range(1, max(h, w) + 1):
        pattern = {}
        valid = True
        for d, color in bands.items():
            k = d % period
            if k in pattern and pattern[k] != color:
                valid = False
                break
            pattern[k] = color
        if valid and len(pattern) == period:
            return [[pattern[(c - r) % period] for c in range(w)]
                    for r in range(h)]

    return [row[:] for row in grid]

